async function openProject(file){if(!file||!await guardProjectSwitch())return;return task('Import du projet…',async()=>{const head=await file.slice(0,9).arrayBuffer();if(head.byteLength<9||new TextDecoder().decode(head.slice(0,5))!=='ONDE1')throw Error('Ce fichier n’est pas un projet Onde.');const len=new DataView(head).getUint32(5,true);if(len>1e7||len+9>file.size)throw Error('Projet invalide.');const meta=JSON.parse(await file.slice(9,9+len).text());if(!Array.isArray(meta.assets))throw Error('Projet invalide.');let pos=9+len;const media=[];for(const a of meta.assets){if(!Number.isSafeInteger(a.size)||a.size<0||pos+a.size>file.size)throw Error('Source audio invalide.');media.push({...a,blob:file.slice(pos,pos+a.size,a.type)});pos+=a.size;}const record={...meta,assets:media},decoded=await hydrateProject(record);activateProject(record,decoded,false);setStatus('Projet importé.');});}
async function exportPortable(){return task('Préparation du projet portable…',async()=>{const record=captureProject(),meta={version:3,state:record.state,view:record.view,assets:record.assets.map(a=>({id:a.id,name:a.name,type:a.blob.type,size:a.blob.size}))},json=new TextEncoder().encode(JSON.stringify(meta)),size=new ArrayBuffer(4);new DataView(size).setUint32(0,json.length,true);download(new Blob(['ONDE1',size,json,...record.assets.map(a=>a.blob)],{type:'application/octet-stream'}),safeName()+'.onde');setStatus('Projet portable exporté.');});}
async function showProjects(){if(busy)return;pause();$('projectsDialog').showModal();$('projectsList').textContent='Chargement…';try{const list=await listProjects();$('projectsList').innerHTML=list.length?list.map(p=>`<article class="project-row"><div><strong>${escape(p.name)}</strong><small>${new Date(p.savedAt).toLocaleString('fr-FR')} · ${stamp(p.duration)} · ${(p.bytes/1048576).toFixed(1)} Mo</small></div><div class="project-row-actions"><button data-project-open="${p.id}" class="primary">Ouvrir</button><button data-project-rename="${p.id}" title="Renommer">✎</button><button data-project-copy="${p.id}" title="Dupliquer">⧉</button><button data-project-delete="${p.id}" title="Supprimer">×</button></div></article>`).join(''):'<p>Aucun projet enregistré.</p>';$('projectsList').querySelectorAll('[data-project-open]').forEach(b=>b.onclick=()=>loadLocalProject(b.dataset.projectOpen));$('projectsList').querySelectorAll('[data-project-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('Supprimer ce projet enregistré dans le navigateur ?'))return;const ok=await task('Suppression…',async()=>{await deleteProject(b.dataset.projectDelete);if(projectId===b.dataset.projectDelete){projectId=null;projectRevision=0;setDirty();try{localStorage.removeItem('onde-last-project');}catch{}}});if(ok)showProjects();});for(const action of ['rename','copy'])$('projectsList').querySelectorAll(`[data-project-${action}]`).forEach(b=>b.onclick=async()=>{const id=b.getAttribute('data-project-'+action);let record;try{record=await readProject(id);}catch(e){setStatus(e.message);return;}if(!record)return;const name=await askName(action==='copy'?'Dupliquer le projet':'Renommer le projet',record.state.name+(action==='copy'?' — copie':''));if(!name)return;const ok=await task('Enregistrement…',async()=>{record.state.name=name;const oldRevision=record.revision;if(action==='copy')record.id=uid();const rev=await writeProject(record,action==='copy'?0:oldRevision);if(action==='rename'&&id===projectId){projectRevision=rev;state.name=name;$('projectName').value=name;}});if(ok)showProjects();});}catch(e){$('projectsList').textContent='Projets indisponibles : '+e.message;}}
async function newProject(){if(!await guardProjectSwitch())return;pause();state={name:'Sans titre',tracks:[track('Voix 01',0),track('Voix 02',1),track('Musique & ambiance',2)],clips:[],markers:[]};assets=new Map();projectId=null;projectRevision=0;history=[];future=[];cursor=0;pps=40;selected=null;dirty=true;resetAnalysisWorker();$('projectsDialog').close();render();setDirty();try{localStorage.removeItem('onde-last-project');}catch{}}
async function exportMix(){if(!state.clips.length)return;const opts={format:$('exportFormat').value,channels:+$('exportChannels').value,rate:+$('exportRate').value,bits:+$('exportBits').value,bitrate:+$('exportBitrate').value,normalize:$('exportNormalize').checked,zone:$('exportRange').value==='zone',target:+$('exportTarget').value};$('exportDialog').close();return task('Rendu du mixage et des traitements…',async()=>{pause();const range=opts.zone?validLoop(state.loop):null;if(opts.zone&&!range)throw Error('Créez une zone avant de l’exporter.');const from=range?.start||0,duration=range?range.end-range.start:end();if(duration>7200)throw Error('Export limité à deux heures par fichier.');await new Promise(r=>setTimeout(r,20));const offline=new OfflineAudioContext(opts.channels,Math.ceil((duration+.04)*opts.rate),opts.rate);await prepareEffects(offline,state);const graph=schedule(offline,from,offline.destination,{to:from+duration,rate:1});let rendered;try{rendered=await offline.startRendering();}finally{graph.cleanup();}const length=Math.ceil(duration*opts.rate),offset=Math.round(.03*opts.rate),channels=Array.from({length:opts.channels},(_,i)=>rendered.getChannelData(i).slice(offset,offset+length));const result=await new Promise((resolve,reject)=>{const worker=new Worker(new URL('./encode-worker.js',import.meta.url));worker.onmessage=({data:m})=>{if(m.error){worker.terminate();reject(Error(m.error));}else if(m.blob){worker.terminate();resolve(m);}else if(m.progress!==undefined)setStatus('Encodage '+opts.format.toUpperCase()+' · '+Math.round(m.progress*100)+' %');};worker.onerror=e=>{worker.terminate();reject(Error(e.message||'Encodage impossible.'));};worker.postMessage({...opts,channels},channels.map(ch=>ch.buffer));});download(result.blob,safeName()+(opts.zone?' — extrait':'')+'.'+opts.format);setStatus('Mixage '+opts.format.toUpperCase()+' exporté.');});}
async function demo(){if(busy)return;await task('Création de la démo sonore…',async()=>{remember();if(!state.tracks.length)state.tracks.push(track('Piste 1',0));const audio=getCtx(),specs=[['Démo · notes de piano',12,220],['Démo · pulsation douce',8,110],['Démo · ambiance',16,330]];for(let i=0;i<specs.length;i++){const [name,duration,f]=specs[i],buffer=audio.createBuffer(1,duration*44100,44100),data=buffer.getChannelData(0);for(let j=0;j<data.length;j++){const t=j/44100,beat=t%(i===1?.5:1.5),freq=f*[1,1.25,1.5,1.125][Math.floor(t/3)%4];data[j]=i===2?.065*Math.sin(t*2*Math.PI*freq)*Math.sin(t*.6)**2:.25*Math.sin(2*Math.PI*freq*t)*Math.exp(-beat*(i===1?18:5))*Math.min(1,beat*120)}const id=uid(),blob=encodeWav(buffer).blob;assets.set(id,{id,name:name+'.wav',blob,buffer,peaks:peaks(buffer)});state.clips.push({id:uid(),asset:id,track:state.tracks[i%state.tracks.length].id,start:i===1?4:0,offset:0,duration,fadeIn:i===2?3:.05,fadeOut:i===2?4:1,gain:1})}selected=state.clips[0].id;fit();render();setStatus('Démo chargée.')})}
