function reorderTrack(id,targetId,after=false){if(id===targetId||busy)return;const moving=state.tracks.find(t=>t.id===id);if(!moving||!state.tracks.some(t=>t.id===targetId))return;remember();state.tracks=state.tracks.filter(t=>t.id!==id);const index=state.tracks.findIndex(t=>t.id===targetId);state.tracks.splice(index+(after?1:0),0,moving);renderTracks();}
