let fxTarget={type:'master',id:null};
function fxOwner(){return fxTarget.type==='master'?state:fxTarget.type==='track'?state.tracks.find(t=>t.id===fxTarget.id):state.clips.find(c=>c.id===fxTarget.id);}
const fxFields=[['highpass','Coupe-bas','Hz',0,200,5],['bass','Graves','dB',-12,12,.5],['presence','Présence de la voix','dB',-12,12,.5],['air','Aigus','dB',-12,12,.5],['threshold','Seuil du compresseur','dB',-50,0,1],['ratio','Ratio',':1',1,12,.5],['knee','Transition douce','dB',0,24,1],['attack','Attaque','ms',1,100,1],['release','Relâchement','ms',20,600,10],['deess','Atténuation des sifflantes','%',0,100,5],['noise','Réduction entre les phrases','%',0,100,5],['noiseThreshold','Seuil du bruit','dB',-65,-20,1],['output','Gain de sortie','dB',-24,12,.5]];
function openFx(type,id=null){if(busy)return;fxTarget={type,id,ids:type==='clip'&&selectionIds().has(id)?[...selectionIds()]:undefined};const owner=fxOwner();if(!owner)return;drawFx();$('fxDialog').showModal();mountSettingsTools($('fxSettingsTools'),()=>fxTarget,true);}
function drawFx(){const owner=fxOwner();if(!owner)return;const f=cleanFx(owner.fx);$('fxTitle').textContent=fxTarget.type==='master'?'Traitements · Master':fxTarget.type==='track'?'Piste · '+owner.name:'Bloc · '+clipName(owner);$('fxEnabled').checked=f.enabled;$('fxPreset').value='custom';$('fxFields').innerHTML=`${groupWarning(targetOwners(fxTarget))}<label class="check"><input type="checkbox" data-fx="compress" ${f.compress?'checked':''}> Compression</label><div class="fx-grid">${fxFields.map(([key,label,unit,min,max,step])=>`<label class="fx-field">${label}<output id="fxValue-${key}">${f[key]} ${unit}</output><input type="range" data-fx="${key}" min="${min}" max="${max}" step="${step}" value="${f[key]}"></label>`).join('')}</div><label class="check"><input type="checkbox" data-fx="limiter" ${f.limiter?'checked':''}> Limiteur de crête (−1 dBFS)</label>`;$('fxFields').querySelectorAll('[data-fx]').forEach(input=>{input.oninput=()=>{const out=$('fxValue-'+input.dataset.fx);if(out)out.textContent=input.value+' '+(fxFields.find(f=>f[0]===input.dataset.fx)?.[2]||'');};input.onchange=()=>changeFx(input.dataset.fx,input.type==='checkbox'?input.checked:+input.value);});}
function changeFx(key,value){const owner=fxOwner();if(!owner)return;const owners=targetOwners(fxTarget);if(!approveGroup(owners)){drawFx();return;}const resume=playing;remember();for(const o of owners)o.fx={...cleanFx(o.fx),[key]:value};renderTracks();if(resume)play();}
$('fxEnabled').onchange=e=>changeFx('enabled',e.target.checked);
$('fxPreset').onchange=e=>{const preset=FX_PRESETS[e.target.value],owner=fxOwner();if(!preset||!owner)return;const owners=targetOwners(fxTarget);if(!approveGroup(owners)){drawFx();return;}const resume=playing;remember();for(const o of owners)o.fx={...preset};drawFx();renderTracks();if(resume)play();};
$('fxPreview').onclick=()=>playing?pause():play();$('masterFx').onclick=()=>openFx('master');

let markerDraft=null;
function drawMarkers(){$('markers').hidden=state.markersVisible===false;$('toggleMarkers').setAttribute('aria-pressed',String(state.markersVisible!==false));$('toggleMarkers').classList.toggle('active',state.markersVisible!==false);$('markers').innerHTML=(state.markers||[]).map(m=>`<div class="timeline-marker ${m.locked?'locked':''}" style="left:${trackWidth()+m.time*pps}px;--marker-color:${m.color}"><div class="marker-tag"><button data-marker="${m.id}" title="${escape(m.note||m.title)}${m.locked?' · verrouillé':' · glisser pour déplacer'}">${escape(m.title)}</button><button data-marker-lock="${m.id}" aria-label="${m.locked?'Déverrouiller':'Verrouiller'} ${escape(m.title)}" aria-pressed="${!!m.locked}" title="${m.locked?'Déverrouiller':'Verrouiller'}">${icon(m.locked?'lock':'unlock')}</button></div></div>`).join('');$('markers').querySelectorAll('[data-marker]').forEach(b=>{b.onpointerdown=startMarkerDrag;b.onclick=e=>{if(e.detail===0)editMarker(b.dataset.marker,b.getBoundingClientRect());};});$('markers').querySelectorAll('[data-marker-lock]').forEach(b=>b.onclick=e=>{e.stopPropagation();const m=state.markers.find(m=>m.id===b.dataset.markerLock);remember();m.locked=!m.locked;drawMarkers();});$('markers').style.clipPath=`inset(0 0 0 ${trackWidth()+$('timelineScroll').scrollLeft}px)`;}
function startMarkerDrag(e){if(e.button!==0||busy)return;e.preventDefault();e.stopPropagation();const m=state.markers.find(m=>m.id===e.currentTarget.dataset.marker);if(!m)return;const rect=e.currentTarget.getBoundingClientRect(),sc=$('timelineScroll'),startX=e.clientX,startTime=m.time,startScroll=sc.scrollLeft,snapshot=JSON.stringify(state);let moved=false;pause();$('markerPopover').hidden=true;
 const move=ev=>{if(m.locked||Math.abs(ev.clientX-startX)<3&&!moved)return;moved=true;const raw=Math.max(0,startTime+(ev.clientX-startX+sc.scrollLeft-startScroll)/pps),edges=[...(state.markers||[]).filter(x=>x.id!==m.id).map(x=>x.time),...snapEdges(state.clips,state.tracks),...(state.zoneMode&&validLoop(state.loop)?[state.loop.start,state.loop.end]:[])],snap=ev.altKey?{time:raw,guide:null}:snapTime(raw,edges,pps);m.time=snap.time;showSnapGuide(snap.guide);drawMarkers();setStatus(stamp(m.time));};
 const up=ev=>{showSnapGuide(null);window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',cancel);if(moved){history.push(snapshot);if(history.length>60)history.shift();future=[];state.markers.sort((a,b)=>a.time-b.time);setDirty();renderTracks();updateButtons();}else editMarker(m.id,rect);};
 const cancel=()=>{showSnapGuide(null);m.time=startTime;window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',cancel);drawMarkers();};window.addEventListener('pointermove',move);window.addEventListener('pointerup',up);window.addEventListener('pointercancel',cancel);}
function editMarker(id=null,rect=null){if(busy)return;pause();const existing=state.markers?.find(m=>m.id===id);markerDraft=existing?{...existing}:{id:uid(),time:cursor,title:'Repère '+((state.markers?.length||0)+1),note:'',color:'#f0ca88'};$('markerTitle').value=markerDraft.title;$('markerTime').value=markerDraft.time.toFixed(2);$('markerColor').value=markerDraft.color;$('markerNote').value=markerDraft.note;$('markerLocked').checked=!!markerDraft.locked;$('markerTime').disabled=!!markerDraft.locked;$('deleteMarker').hidden=!existing;const p=$('markerPopover');p.hidden=false;p.style.left=Math.max(8,Math.min(window.innerWidth-338,rect?.left||window.innerWidth/2-165))+'px';p.style.top=Math.max(12,Math.min(window.innerHeight-300,(rect?.bottom||120)+8))+'px';$('markerTitle').focus();}
$('markerForm').onsubmit=e=>{e.preventDefault();if(!markerDraft)return;const time=markerDraft.locked&&$('markerLocked').checked?markerDraft.time:+$('markerTime').value;if(!Number.isFinite(time)||time<0)return;remember();const marker={...markerDraft,time,locked:$('markerLocked').checked,title:$('markerTitle').value.trim()||'Repère',note:$('markerNote').value,color:$('markerColor').value};state.markers??=[];const i=state.markers.findIndex(m=>m.id===marker.id);if(i>=0)state.markers[i]=marker;else state.markers.push(marker);state.markers.sort((a,b)=>a.time-b.time);$('markerPopover').hidden=true;renderTracks();};
$('deleteMarker').onclick=()=>{remember();state.markers=(state.markers||[]).filter(m=>m.id!==markerDraft.id);$('markerPopover').hidden=true;renderTracks();};$('cancelMarker').onclick=()=>$('markerPopover').hidden=true;$('addMarker').onclick=()=>editMarker();
