let analysisWorker=null,analysedSources=new Set();
function resetAnalysisWorker(){analysisWorker?.terminate();analysisWorker=null;analysedSources=new Set();}
function runSourceAnalysis(asset,settings){analysisWorker??=new Worker(new URL('./analysis-worker.js',import.meta.url),{type:'module'});return new Promise((resolve,reject)=>{const id=uid();analysisWorker.onmessage=({data:m})=>{if(m.id!==id)return;if(m.error)reject(Error(m.error));else if(m.segments){analysedSources.add(asset.id);resolve(m.segments);}else if(m.progress!==undefined)setStatus('Analyse de '+assetName(asset)+' · '+Math.round(m.progress*100)+' %');};analysisWorker.onerror=e=>{resetAnalysisWorker();reject(Error(e.message||'Analyse impossible.'));};const message={id,asset:asset.id,...settings};let transfer=[];if(!analysedSources.has(asset.id)){message.samples=asset.buffer.getChannelData(0).slice();if(asset.buffer.numberOfChannels>1){for(let ch=1;ch<asset.buffer.numberOfChannels;ch++){const other=asset.buffer.getChannelData(ch);for(let i=0;i<message.samples.length;i++)message.samples[i]+=other[i];}for(let i=0;i<message.samples.length;i++)message.samples[i]/=asset.buffer.numberOfChannels;}message.rate=asset.buffer.sampleRate;transfer=[message.samples.buffer];}analysisWorker.postMessage(message,transfer);});}
function openAnalysis(){const a=state.analysis||{};$('analysisTrack').innerHTML='<option value="all">Toutes les pistes</option>'+state.tracks.map(t=>`<option value="${t.id}">${escape(t.name)}</option>`).join('');$('analysisTrack').value=a.track||'all';$('analysisSensitivity').value=a.sensitivity||55;$('sensitivityValue').textContent=(a.sensitivity||55)+' %';$('analysisDuration').value=a.minDuration||.5;$('analysisVisible').checked=a.visible!==false;$('analysisSummary').textContent=Object.values(a.results||{}).reduce((n,s)=>n+s.length,0)+' zone(s) repérée(s) dans les sources.';$('analysisDialog').showModal();}
$('analyseButton').onclick=openAnalysis;$('analysisSensitivity').oninput=e=>$('sensitivityValue').textContent=e.target.value+' %';
$('analysisVisible').onchange=e=>{remember();state.analysis??={};state.analysis.visible=e.target.checked;renderTracks();};
$('clearAnalysis').onclick=()=>{remember();state.analysis={...state.analysis,results:{}};$('analysisSummary').textContent='Résultats effacés.';renderTracks();};
$('runAnalysis').onclick=async()=>{const settings={sensitivity:+$('analysisSensitivity').value,minDuration:clamp(+$('analysisDuration').value||.5,.2,3),track:$('analysisTrack').value,visible:$('analysisVisible').checked},ids=[...new Set(state.clips.filter(c=>settings.track==='all'||c.track===settings.track).map(c=>c.asset))];if(!ids.length){$('analysisSummary').textContent='Aucun bloc à analyser sur ces pistes.';return;}await task('Analyse des hésitations possibles…',async()=>{pause();const results={};for(const id of ids)results[id]=await runSourceAnalysis(assets.get(id),settings);remember();state.analysis={...settings,results};renderTracks();$('analysisSummary').textContent=Object.values(results).reduce((n,s)=>n+s.length,0)+' zone(s) possible(s), à vérifier à l’écoute.';setStatus('Analyse terminée.');});};

