function removeAsset(id){if(busy||!projectAssets().some(a=>a.id===id))return;const used=state.clips.filter(c=>c.asset===id);if(used.length&&!confirm(`Ce fichier est utilisé par ${used.length} bloc(s). Le retirer supprimera aussi ces blocs du montage. Continuer ?`))return;remember();state.removedAssets=[...new Set([...(state.removedAssets||[]),id])];state.clips=state.clips.filter(c=>c.asset!==id);if(state.mediaNames)delete state.mediaNames[id];if(state.analysis?.results)delete state.analysis.results[id];if(!state.clips.some(c=>c.id===selected))selectOnly(null);syncCrossfades(state.clips);render();setStatus('Fichier retiré du projet · Annuler permet de le restaurer.');}

function positionClipLabels(){const sc=$('timelineScroll');for(const el of $('tracks').querySelectorAll('.clip')){const c=state.clips.find(c=>c.id===el.dataset.clip),label=el.querySelector('.clip-name');if(!c||!label)continue;label.style.left=Math.max(4,sc.scrollLeft-c.start*pps+4)+'px';label.style.maxWidth=Math.max(0,sc.clientWidth-trackWidth()-12)+'px';}}

function removeTrack(id){if(busy)return;const t=state.tracks.find(t=>t.id===id);if(!t)return;const clips=state.clips.filter(c=>c.track===id);if(clips.length&&!confirm(`Supprimer la piste « ${t.name} » et ses ${clips.length} bloc(s) ? Les fichiers sources seront conservés.`))return;remember();state.tracks=state.tracks.filter(t=>t.id!==id);state.clips=state.clips.filter(c=>c.track!==id);if(!state.clips.some(c=>c.id===selected))selectOnly(null);if(state.analysis?.track===id)state.analysis.track='all';if(fxTarget.type==='track'&&fxTarget.id===id)$('fxDialog').close();render();setStatus('Piste supprimée · Cmd/Ctrl+Z pour annuler.');}
